<template><section class="container page"><div class="breadcrumb">首页　/　商品详情</div><div class="detail"><div class="detail-image" :style="{background:product.color}"><span>{{product.emoji}}</span><small>{{product.tag}}</small></div><div class="detail-copy"><span class="eyebrow">FRESH SELECT · {{product.origin}}</span><h1>{{product.name}}</h1><p class="detail-desc">{{product.desc}}</p><div class="detail-rating">★★★★★ <b>{{product.rating}}</b>　<span>{{product.sales}} 人已购买</span></div><div class="detail-price"><strong>¥{{product.price.toFixed(1)}}</strong><del>¥{{product.oldPrice.toFixed(1)}}</del><em>会员价</em></div><div class="service-pills"><span>✓ 冷链配送</span><span>✓ 不新鲜包退</span><span>✓ 产地直采</span></div><div class="quantity"><span>数量</span><button @click="quantity=Math.max(1,quantity-1)">−</button><b>{{quantity}}</b><button @click="quantity++">＋</button></div><div class="detail-actions"><button class="secondary" @click="add">加入购物车</button><button class="primary" @click="buy">立即购买</button></div></div></div><div class="detail-tabs"><b>商品详情</b><span>用户评价（128）</span><span>配送说明</span><span>售后保障</span></div><div class="detail-panel"><h3>新鲜看得见</h3><p>鲜选坚持从源头把控品质，每一份商品都经过严格筛选。下单后由附近门店拣货，专业冷链配送，让新鲜以最好的状态抵达你的餐桌。</p><div class="detail-highlights"><span>🌱 严选产地</span><span>🧊 全程冷链</span><span>🚚 极速送达</span><span>♧ 售后无忧</span></div></div></section></template>
<script setup>import { computed, ref, inject } from 'vue'; import { useRoute,useRouter } from 'vue-router'; import { findProduct,addToCart } from '../data'; const route=useRoute(),router=useRouter(),notify=inject('notify'),product=computed(()=>findProduct(route.params.id)),quantity=ref(1); const add=()=>{addToCart(product.value.id,quantity.value);notify('已加入购物车')}; const buy=()=>{add();router.push('/checkout')}</script>
